INSERT INTO `core_component` VALUES (1,'Home Full Page','<div class=\"container main-container\">\r\n        <!-- Home Section -->\r\n        <section id=\"home\">\r\n            <!-- Holographic Header -->\r\n            <div class=\"header\">\r\n                <div class=\"avatar-container\">\r\n                    <div class=\"hologram-ring\"></div>\r\n                    <div class=\"hologram-ring ring-2\"></div>\r\n                    <div class=\"hologram-ring ring-3\"></div>\r\n                    <div class=\"avatar\">\r\n                        <span class=\"avatar-text\">KA</span>\r\n                        <div class=\"scan-line\"></div>\r\n                    </div>\r\n                </div>\r\n                <div class=\"digital-glitch\" data-text=\"SYSTEM INITIALIZING\">SYSTEM INITIALIZING</div>\r\n            </div>\r\n\r\n            <!-- AI Status Panel -->\r\n            <div class=\"ai-status-panel\">\r\n                <div class=\"status-item\">\r\n                    <span class=\"status-label\">Neural Networks</span>\r\n                    <span class=\"status-value\">ACTIVE</span>\r\n                </div>\r\n                <div class=\"status-item\">\r\n                    <span class=\"status-label\">Code Generation</span>\r\n                    <span class=\"status-value\">ONLINE</span>\r\n                </div>\r\n                <div class=\"status-item\">\r\n                    <span class=\"status-label\">Innovation Engine</span>\r\n                    <span class=\"status-value\">OPTIMIZED</span>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- Main Content -->\r\n            <div class=\"content-section\">\r\n                <h1 class=\"main-title\">\r\n                    <span class=\"title-line\">THE DIGITAL</span>\r\n                    <span class=\"title-line\">ARCHITECT</span>\r\n                    <div class=\"typing-cursor\">_</div>\r\n                </h1>\r\n                \r\n                <div class=\"subtitle-container\">\r\n                    <div class=\"terminal-prefix\">root@kabhishek18:~$ </div>\r\n                    <div class=\"typewriter\" id=\"typewriter\"></div>\r\n                </div>\r\n                \r\n                <!-- AI Tags -->\r\n                <div class=\"ai-tags\">\r\n                    <span class=\"ai-tag\">The Digital Architect</span>\r\n                    <span class=\"ai-tag\">The AI Enthusiast</span>\r\n                    <span class=\"ai-tag\">Neural Engineer</span>\r\n                    <span class=\"ai-tag\">Code Architect</span>\r\n                    <span class=\"ai-tag\">LLM Engineerus</span>\r\n                    <span class=\"ai-tag\">Digital Innovator</span>\r\n                </div>\r\n                \r\n                <!-- Mysterious Description -->\r\n                <div class=\"description\">\r\n                    <p>In the shadows of the digital realm, where algorithms dance with creativity and neural networks whisper secrets of tomorrow, I forge the future one line of code at a time.</p>\r\n                    \r\n                    <div class=\"stats-grid\">\r\n                        <div class=\"stat-item\">\r\n                            <span class=\"stat-number\">9+</span>\r\n                            <span class=\"stat-label\">Years in the Matrix</span>\r\n                        </div>\r\n                        <div class=\"stat-item\">\r\n                            <span class=\"stat-number\">50+</span>\r\n                            <span class=\"stat-label\">Digital Artifacts</span>\r\n                        </div>\r\n                        <div class=\"stat-item\">\r\n                            <span class=\"stat-number\">4</span>\r\n                            <span class=\"stat-label\">PyPI Creations</span>\r\n                        </div>\r\n                        <div class=\"stat-item\">\r\n                            <span class=\"stat-number\">∞</span>\r\n                            <span class=\"stat-label\">Possibilities</span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </section>\r\n\r\n        <!-- About Section -->\r\n        <section id=\"about\" style=\"margin: 5rem 0;\">\r\n            <h2 style=\"font-family: \'Orbitron\', monospace; font-size: 2.5rem; text-align: center; margin-bottom: 3rem; color: var(--accent-cyan);\">\r\n                ABOUT THE ARCHITECT\r\n            </h2>\r\n            \r\n            <!-- AI Progress System -->\r\n            <div class=\"ai-progress-section\">\r\n                <div class=\"progress-header\">\r\n                    <span class=\"progress-label\">\r\n                        <i class=\"fas fa-brain\"></i>\r\n                        CONSCIOUSNESS INTEGRATION\r\n                    </span>\r\n                    <span class=\"progress-percentage\">87%</span>\r\n                </div>\r\n                <div class=\"progress-container\">\r\n                    <div class=\"progress-bar\">\r\n                        <div class=\"progress-fill\"></div>\r\n                        <div class=\"progress-glow\"></div>\r\n                    </div>\r\n                    <div class=\"progress-nodes\">\r\n                        <div class=\"node active\"></div>\r\n                        <div class=\"node active\"></div>\r\n                        <div class=\"node active\"></div>\r\n                        <div class=\"node active\"></div>\r\n                        <div class=\"node active\"></div>\r\n                        <div class=\"node\"></div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- SVG Illustration Space -->\r\n            <div class=\"svg-container\">\r\n                <div class=\"svg-frame\">\r\n                     <div class=\"svg-border-effects\">\r\n                                <div class=\"corner top-left\"></div>\r\n                                <div class=\"corner top-right\"></div>\r\n                                <div class=\"corner bottom-left\"></div>\r\n                                <div class=\"corner bottom-right\"></div>\r\n                    </div>\r\n                    <div class=\"row\">\r\n                        <div class=\"col-sm-6\">\r\n                            <div class=\"svg-placeholder\">\r\n                                <div class=\"svg-loading\">\r\n                                    <i class=\"fas fa-robot\"></i> \r\n                                    <br>\r\n                                    <span class=\"text-label\">AI VISUALIZATION</span>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-sm-6\">\r\n                            \r\n                           \r\n                            <!-- Add SVG Here -->\r\n                            <!-- ======== Website Blueprint SVG ======== -->\r\n                            <svg\r\n                            id=\"website-blueprint-svg\"\r\n                            viewBox=\"0 0 400 500\"\r\n                            xmlns=\"http://www.w3.org/2000/svg\"\r\n                            preserveAspectRatio=\"xMidYMid meet\"\r\n                            aria-labelledby=\"svgBlueprintTitle\"\r\n                            >\r\n                            <title id=\"svgBlueprintTitle\">Website Architecture Blueprint Visualization</title>\r\n\r\n                            <style>\r\n                                :root {\r\n                                --accent-cyan: #00d9ff;\r\n                                --accent-green: #00ff88;\r\n                                --accent-purple: #a855f7;\r\n                                --text-muted: #a1a1a1;\r\n                                }\r\n\r\n                                #website-blueprint-svg {\r\n                                    width: 100%;\r\n                                    height: 100%;\r\n                                    position: relative;\r\n                                    z-index: 1;\r\n                                    opacity: 0;\r\n                                    cursor: default;\r\n                                    animation: fadeInSVG 1s ease-in-out 0.5s forwards;\r\n                                    font-family: \'JetBrains Mono\', monospace;\r\n                                }\r\n\r\n                                @keyframes fadeInSVG {\r\n                                    to { opacity: 1; }\r\n                                }\r\n\r\n                                /* --- Base Elements & Grid --- */\r\n                                .blueprint-bg {\r\n                                    fill: rgba(10, 10, 10, 0.5); /* Dark background inside the SVG */\r\n                                }\r\n                                .grid-line {\r\n                                    stroke: var(--accent-cyan);\r\n                                    stroke-width: 0.2;\r\n                                    opacity: 0.2;\r\n                                }\r\n\r\n                                /* --- Wireframe Components --- */\r\n                                .wireframe-box {\r\n                                    fill: none;\r\n                                    stroke: var(--accent-cyan);\r\n                                    stroke-width: 0.75;\r\n                                    stroke-opacity: 0.8;\r\n                                    rx: 2; /* Slightly rounded corners */\r\n                                    transition: stroke-opacity 0.3s ease;\r\n                                }\r\n                                .wireframe-fill {\r\n                                    fill: var(--accent-cyan);\r\n                                    opacity: 0.05;\r\n                                    transition: opacity 0.3s ease;\r\n                                }\r\n\r\n                                /* --- Text & Labels --- */\r\n                                .blueprint-text {\r\n                                    font-size: 10px;\r\n                                    fill: var(--text-muted);\r\n                                    text-anchor: middle;\r\n                                    dominant-baseline: middle;\r\n                                    letter-spacing: 0.5px;\r\n                                    text-transform: uppercase;\r\n                                }\r\n                                .main-label {\r\n                                    font-size: 14px;\r\n                                    fill: var(--accent-cyan);\r\n                                    font-weight: bold;\r\n                                }\r\n                                .blueprint-text.typing-effect {\r\n                                    opacity: 0;\r\n                                    animation: typeIn 1s forwards;\r\n                                }\r\n\r\n                                @keyframes typeIn {\r\n                                    0% { opacity: 0; }\r\n                                    1% { opacity: 1; } /* Create a flicker effect */\r\n                                    100% { opacity: 1; }\r\n                                }\r\n                                \r\n                                /* Animation Delays for Text */\r\n                                #label-nav { animation-delay: 0.5s; }\r\n                                #label-hero { animation-delay: 1.0s; }\r\n                                #label-about { animation-delay: 1.5s; }\r\n                                #label-projects { animation-delay: 2.0s; }\r\n                                #label-contact { animation-delay: 2.5s; }\r\n                                #label-footer { animation-delay: 3.0s; }\r\n\r\n                                /* --- Data Flow Lines --- */\r\n                                .flow-line {\r\n                                    fill: none;\r\n                                    stroke: var(--accent-purple);\r\n                                    stroke-width: 1;\r\n                                    stroke-dasharray: 200;\r\n                                    stroke-dashoffset: 200;\r\n                                    opacity: 0.8;\r\n                                    animation: drawLine 2s ease-out forwards;\r\n                                }\r\n                                .flow-packet {\r\n                                    fill: var(--accent-green);\r\n                                    r: 2.5;\r\n                                    opacity: 0;\r\n                                    animation: movePacket 2s ease-in-out infinite;\r\n                                }\r\n\r\n                                @keyframes drawLine {\r\n                                    to { stroke-dashoffset: 0; }\r\n                                }\r\n                                @keyframes movePacket {\r\n                                    0% { opacity: 0; }\r\n                                    25% { opacity: 1; }\r\n                                    75% { opacity: 1; }\r\n                                    100% { opacity: 0; }\r\n                                }\r\n\r\n                                /* Animation Delays for Flow */\r\n                                #flow1 { animation-delay: 1.0s; }\r\n                                #flow2 { animation-delay: 1.5s; }\r\n                                #flow3 { animation-delay: 2.0s; }\r\n                                #flow4 { animation-delay: 2.5s; }\r\n                                #packet1 { animation-delay: 1.0s; }\r\n                                #packet2 { animation-delay: 1.5s; }\r\n                                #packet3 { animation-delay: 2.0s; }\r\n                                #packet4 { animation-delay: 2.5s; }\r\n\r\n                                /* --- Interactivity on Hover --- */\r\n                                .wireframe-group:hover .wireframe-box {\r\n                                    stroke-opacity: 1;\r\n                                }\r\n                                .wireframe-group:hover .wireframe-fill {\r\n                                    opacity: 0.15;\r\n                                }\r\n                                .wireframe-group:hover .main-label {\r\n                                    text-shadow: 0 0 5px var(--accent-cyan);\r\n                                }\r\n                                \r\n                            </style>\r\n\r\n                            <defs>\r\n                                <!-- Grid pattern to be reused -->\r\n                                <pattern id=\"gridPattern\" width=\"20\" height=\"20\" patternUnits=\"userSpaceOnUse\">\r\n                                <path class=\"grid-line\" d=\"M 20 0 L 0 0 0 20\" fill=\"none\" />\r\n                                </pattern>\r\n                            </defs>\r\n\r\n                            <!-- Background Grid -->\r\n                            <rect class=\"blueprint-bg\" width=\"400\" height=\"500\" />\r\n                            <rect fill=\"url(#gridPattern)\" width=\"400\" height=\"500\" />\r\n\r\n                            <!-- Main Blueprint Structure -->\r\n                            <g id=\"blueprint-structure\">\r\n\r\n                                <!-- Header / Navigation -->\r\n                                <g class=\"wireframe-group\">\r\n                                <rect class=\"wireframe-fill\" x=\"50\" y=\"30\" width=\"300\" height=\"50\" />\r\n                                <rect class=\"wireframe-box\" x=\"50\" y=\"30\" width=\"300\" height=\"50\" />\r\n                                <text id=\"label-nav\" class=\"blueprint-text main-label typing-effect\" x=\"200\" y=\"55\">Navigation</text>\r\n                                </g>\r\n\r\n                                <!-- Hero Section -->\r\n                                <g class=\"wireframe-group\">\r\n                                <rect class=\"wireframe-fill\" x=\"50\" y=\"100\" width=\"300\" height=\"100\" />\r\n                                <rect class=\"wireframe-box\" x=\"50\" y=\"100\" width=\"300\" height=\"100\" />\r\n                                <text id=\"label-hero\" class=\"blueprint-text main-label typing-effect\" x=\"200\" y=\"150\">Hero Section</text>\r\n                                </g>\r\n\r\n                                <!-- About Section -->\r\n                                <g class=\"wireframe-group\">\r\n                                <rect class=\"wireframe-fill\" x=\"50\" y=\"220\" width=\"140\" height=\"80\" />\r\n                                <rect class=\"wireframe-box\" x=\"50\" y=\"220\" width=\"140\" height=\"80\" />\r\n                                <text id=\"label-about\" class=\"blueprint-text typing-effect\" x=\"120\" y=\"260\">About</text>\r\n                                </g>\r\n                                \r\n                                <!-- Projects Section -->\r\n                                <g class=\"wireframe-group\">\r\n                                <rect class=\"wireframe-fill\" x=\"210\" y=\"220\" width=\"140\" height=\"80\" />\r\n                                <rect class=\"wireframe-box\" x=\"210\" y=\"220\" width=\"140\" height=\"80\" />\r\n                                <text id=\"label-projects\" class=\"blueprint-text typing-effect\" x=\"280\" y=\"260\">Projects</text>\r\n                                </g>\r\n\r\n                                <!-- Contact Section -->\r\n                                <g class=\"wireframe-group\">\r\n                                <rect class=\"wireframe-fill\" x=\"50\" y=\"320\" width=\"300\" height=\"80\" />\r\n                                <rect class=\"wireframe-box\" x=\"50\" y=\"320\" width=\"300\" height=\"80\" />\r\n                                <text id=\"label-contact\" class=\"blueprint-text main-label typing-effect\" x=\"200\" y=\"360\">Contact</text>\r\n                                </g>\r\n\r\n                                <!-- Footer -->\r\n                                <g class=\"wireframe-group\">\r\n                                <rect class=\"wireframe-fill\" x=\"50\" y=\"420\" width=\"300\" height=\"50\" />\r\n                                <rect class=\"wireframe-box\" x=\"50\" y=\"420\" width=\"300\" height=\"50\" />\r\n                                <text id=\"label-footer\" class=\"blueprint-text typing-effect\" x=\"200\" y=\"445\">Footer</text>\r\n                                </g>\r\n\r\n                            </g>\r\n                            \r\n                            <!-- Data Flow Lines & Packets -->\r\n                            <g id=\"data-flow\">\r\n                                <!-- Lines -->\r\n                                <path id=\"flow1\" class=\"flow-line\" d=\"M 200,80 v 20\"/>\r\n                                <path id=\"flow2\" class=\"flow-line\" d=\"M 200,200 v 20\"/>\r\n                                <path id=\"flow3\" class=\"flow-line\" d=\"M 120,300 v 20\"/>\r\n                                <path id=\"flow4\" class=\"flow-line\" d=\"M 280,300 v 20\"/>\r\n\r\n                                <!-- Packets -->\r\n                                <circle id=\"packet1\" class=\"flow-packet\">\r\n                                    <animateMotion dur=\"2s\" repeatCount=\"indefinite\" path=\"M 200,80 v 20\"/>\r\n                                </circle>\r\n                                <circle id=\"packet2\" class=\"flow-packet\">\r\n                                    <animateMotion dur=\"2s\" repeatCount=\"indefinite\" path=\"M 200,200 v 20\"/>\r\n                                </circle>\r\n                                <circle id=\"packet3\" class=\"flow-packet\">\r\n                                    <animateMotion dur=\"2s\" repeatCount=\"indefinite\" path=\"M 120,300 v 20\"/>\r\n                                </circle>\r\n                                <circle id=\"packet4\" class=\"flow-packet\">\r\n                                    <animateMotion dur=\"2s\" repeatCount=\"indefinite\" path=\"M 280,300 v 20\"/>\r\n                                </circle>\r\n                            </g>\r\n\r\n                            </svg>\r\n                            <!-- ======== End of SVG ======== -->\r\n\r\n                        </div>      \r\n\r\n                    </div>\r\n                   \r\n                </div>\r\n            </div>\r\n        </section>\r\n\r\n        <!-- Projects Section -->\r\n        <section id=\"projects\" style=\"margin: 5rem 0;\">\r\n            <h2 style=\"font-family: \'Orbitron\', monospace; font-size: 2.5rem; text-align: center; margin-bottom: 3rem; color: var(--accent-cyan);\">\r\n                DIGITAL DOMAINS\r\n            </h2>\r\n            \r\n            <!-- Domains Grid -->\r\n            <div class=\"domains-grid\">\r\n                <div class=\"domain-card\" data-domain=\"e-commerce\">\r\n                    <div class=\"domain-icon\">🛒</div>\r\n                    <div class=\"domain-title\">E-Commerce Nexus</div>\r\n                    <div class=\"domain-experience\">7+ years</div>\r\n                </div>\r\n                <div class=\"domain-card\" data-domain=\"aviation\">\r\n                    <div class=\"domain-icon\">✈️</div>\r\n                    <div class=\"domain-title\">Aviation Systems</div>\r\n                    <div class=\"domain-experience\">4+ years</div>\r\n                </div>\r\n                <div class=\"domain-card\" data-domain=\"edtech\">\r\n                    <div class=\"domain-icon\">🎓</div>\r\n                    <div class=\"domain-title\">EdTech Revolution</div>\r\n                    <div class=\"domain-experience\">5+ years</div>\r\n                </div>\r\n                <div class=\"domain-card\" data-domain=\"security\">\r\n                    <div class=\"domain-icon\">🔐</div>\r\n                    <div class=\"domain-title\">Security Feature</div>\r\n                    <div class=\"domain-experience\">7+ years</div>\r\n                </div>\r\n            </div>\r\n        </section>\r\n\r\n        <!-- Contact Section -->\r\n        <section id=\"contact\">\r\n            <!-- Contact Matrix -->\r\n            <div class=\"contact-matrix\">\r\n                <div class=\"matrix-header\">\r\n                    <h3>\r\n                        <i class=\"fas fa-satellite-dish\"></i>\r\n                        ESTABLISH CONNECTION\r\n                    </h3>\r\n                    <div class=\"signal-strength\">\r\n                        <span class=\"signal-bar\"></span>\r\n                        <span class=\"signal-bar\"></span>\r\n                        <span class=\"signal-bar\"></span>\r\n                        <span class=\"signal-bar\"></span>\r\n                    </div>\r\n                </div>\r\n                \r\n                <div class=\"contact-content\">\r\n                    <div class=\"email-terminal\">\r\n                        <div class=\"terminal-header\">\r\n                            <span class=\"terminal-title\">secure_channel.py</span>\r\n                            <div class=\"terminal-controls\">\r\n                                <span class=\"control minimize\"></span>\r\n                                <span class=\"control maximize\"></span>\r\n                                <span class=\"control close\"></span>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"terminal-body\">\r\n                            <div class=\"terminal-line\">\r\n                                <span class=\"prompt\">>>> </span>\r\n                                <span class=\"command\">initiate_contact()</span>\r\n                            </div>\r\n                            <div class=\"terminal-line\">\r\n                                <span class=\"output\">Establishing secure connection...</span>\r\n                            </div>\r\n                            <div class=\"terminal-line\">\r\n                                <span class=\"output\">Channel: </span>\r\n                                <a href=\"mailto:developer@kabhishek18.com\" class=\"email-link\">\r\n                                    developer@kabhishek18.com\r\n                                </a>\r\n                            </div>\r\n                            <div class=\"terminal-line\">\r\n                                <span class=\"output\">Status: READY</span>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                    \r\n                    <!-- Social Links -->\r\n                    <div class=\"social-matrix\">\r\n                        <div class=\"social-title\">NETWORK NODES</div>\r\n                        <div class=\"social-links\">\r\n                            <a href=\"https://github.com/kabhishek18\" class=\"social-link\" target=\"_blank\">\r\n                                <i class=\"fab fa-github\"></i>\r\n                                <span>GitHub</span>\r\n                            </a>\r\n                            <a href=\"https://linkedin.com/in/kabhishek18\" class=\"social-link\" target=\"_blank\">\r\n                                <i class=\"fab fa-linkedin\"></i>\r\n                                <span>LinkedIn</span>\r\n                            </a>\r\n                            <a href=\"https://twitter.com/kabhishek18\" class=\"social-link\" target=\"_blank\">\r\n                                <i class=\"fab fa-twitter\"></i>\r\n                                <span>Twitter</span>\r\n                            </a>\r\n                            <a href=\"https://www.freelancer.com/u/kabhishek18\" class=\"social-link\" target=\"_blank\">\r\n                                <i class=\"fas fa-briefcase\"></i>\r\n                                <span>Freelancer</span>\r\n                            </a>\r\n                            <a href=\"https://orcid.org/0009-0006-6321-2424\" class=\"social-link\" target=\"_blank\">\r\n                                <i class=\"fas fa-graduation-cap\"></i>\r\n                                <span>ORCID</span>\r\n                            </a>\r\n                            \r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </section>\r\n\r\n<amp-auto-ads type=\"adsense\"\r\n        data-ad-client=\"ca-pub-6078293202282096\">\r\n</amp-auto-ads>\r\n         <!-- AI Footer -->\r\n        <footer class=\"ai-footer\">\r\n            <div class=\"footer-text\">\r\n                \"In a world where artificial intelligence meets human creativity, \r\n                infinite possibilities emerge from the void of digital consciousness.\"\r\n            </div>\r\n            <div class=\"footer-signature\">\r\n                — The Digital Architect\r\n            </div>\r\n            <p style=\"color: var(--text-muted); font-size: var(--text-sm); margin-top: 2rem;\">\r\n                &copy; 2025 Kumar Abhishek. All rights reserved. | <a href=\"/privacy\" style=\"color: var(--accent-cyan); text-decoration: none;\">Privacy Policy</a> | <a href=\"/sitemap.xml\" style=\"color: var(--accent-cyan); text-decoration: none;\">\r\n                        <i class=\"fas fa-sitemap\"></i>\r\n                        Sitemap\r\n                    </a>\r\n            </p>\r\n        </footer>\r\n</div>\r\n\r\n<script>\r\n    // Enhanced Navigation Script\r\n    document.addEventListener(\'DOMContentLoaded\', function() {\r\n        // Mobile menu toggle\r\n        const mobileMenuToggle = document.getElementById(\'mobileMenuToggle\');\r\n        const mobileMenu = document.getElementById(\'mobileMenu\');\r\n        const navLinks = document.querySelectorAll(\'.nav-link\');\r\n        \r\n        mobileMenuToggle.addEventListener(\'click\', () => {\r\n            mobileMenu.classList.toggle(\'active\');\r\n            const icon = mobileMenuToggle.querySelector(\'i\');\r\n            icon.classList.toggle(\'fa-bars\');\r\n            icon.classList.toggle(\'fa-times\');\r\n        });\r\n        \r\n        // Close mobile menu when clicking on a link\r\n        navLinks.forEach(link => {\r\n            link.addEventListener(\'click\', () => {\r\n                mobileMenu.classList.remove(\'active\');\r\n                const icon = mobileMenuToggle.querySelector(\'i\');\r\n                icon.classList.add(\'fa-bars\');\r\n                icon.classList.remove(\'fa-times\');\r\n            });\r\n        });\r\n        \r\n        // Scroll progress indicator\r\n        const scrollIndicator = document.getElementById(\'scrollIndicator\');\r\n        window.addEventListener(\'scroll\', () => {\r\n            const scrollTop = window.pageYOffset;\r\n            const docHeight = document.body.offsetHeight - window.innerHeight;\r\n            const scrollPercent = (scrollTop / docHeight) * 100;\r\n            scrollIndicator.style.width = scrollPercent + \'%\';\r\n        });\r\n        \r\n        // Smooth scrolling for navigation links\r\n        document.querySelectorAll(\'a[href^=\"#\"]\').forEach(anchor => {\r\n            anchor.addEventListener(\'click\', function (e) {\r\n                e.preventDefault();\r\n                const target = document.querySelector(this.getAttribute(\'href\'));\r\n                if (target) {\r\n                    target.scrollIntoView({\r\n                        behavior: \'smooth\',\r\n                        block: \'start\'\r\n                    });\r\n                }\r\n            });\r\n        });\r\n        \r\n        // Active navigation highlighting\r\n        const sections = document.querySelectorAll(\'section[id]\');\r\n        const navItems = document.querySelectorAll(\'.nav-link[href^=\"#\"]\');\r\n        \r\n        function highlightNavigation() {\r\n            const scrollPos = window.scrollY + 100;\r\n            \r\n            sections.forEach(section => {\r\n                const sectionTop = section.offsetTop;\r\n                const sectionHeight = section.offsetHeight;\r\n                const sectionId = section.getAttribute(\'id\');\r\n                \r\n                if (scrollPos >= sectionTop && scrollPos < sectionTop + sectionHeight) {\r\n                    navItems.forEach(item => {\r\n                        item.classList.remove(\'active\');\r\n                        if (item.getAttribute(\'href\') === `#${sectionId}`) {\r\n                            item.classList.add(\'active\');\r\n                        }\r\n                    });\r\n                }\r\n            });\r\n        }\r\n        \r\n        window.addEventListener(\'scroll\', highlightNavigation);\r\n        \r\n        // Navigation background on scroll\r\n        const mainNav = document.getElementById(\'mainNav\');\r\n        window.addEventListener(\'scroll\', () => {\r\n            if (window.scrollY > 50) {\r\n                mainNav.style.background = \'rgba(10, 10, 10, 0.98)\';\r\n                mainNav.style.boxShadow = \'0 5px 20px rgba(0, 255, 255, 0.1)\';\r\n            } else {\r\n                mainNav.style.background = \'rgba(10, 10, 10, 0.95)\';\r\n                mainNav.style.boxShadow = \'none\';\r\n            }\r\n        });\r\n    });\r\n</script>','2025-07-11 09:03:39.993000','2025-10-10 05:05:53.386745','home-full-page'),(2,'Privacy','<!-- Main Container -->\r\n    <div class=\"container privacy-container\">\r\n        <!-- Privacy Header -->\r\n        <div class=\"privacy-header\">\r\n            <div class=\"privacy-icon\">\r\n                <i class=\"fas fa-shield-alt\"></i>\r\n            </div>\r\n            <h1 class=\"privacy-title\">Privacy Policy</h1>\r\n            <div class=\"privacy-subtitle\">\r\n                Your privacy is critically important to us\r\n            </div>\r\n            <div class=\"last-updated\">\r\n                Last updated: <span class=\"update-date\">January 2025</span>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Privacy Content -->\r\n        <div class=\"privacy-content\">\r\n            <section class=\"privacy-section\">\r\n                <h2 class=\"section-title\">\r\n                    <i class=\"fas fa-info-circle\"></i>\r\n                    Introduction\r\n                </h2>\r\n                <div class=\"section-content\">\r\n                    <p>Welcome to Kumar Abhishek\'s digital portfolio. This Privacy Policy explains how I collect, use, and protect your information when you visit this website. By using this website, you agree to the collection and use of information in accordance with this policy.</p>\r\n                </div>\r\n            </section>\r\n\r\n            <section class=\"privacy-section\">\r\n                <h2 class=\"section-title\">\r\n                    <i class=\"fas fa-database\"></i>\r\n                    Information Collection\r\n                </h2>\r\n                <div class=\"section-content\">\r\n                    <h3>Information I Collect</h3>\r\n                    <ul class=\"privacy-list\">\r\n                        <li><strong>Personal Information:</strong> When you contact me via email, I may collect your name, email address, and any message content you provide.</li>\r\n                        <li><strong>Usage Data:</strong> I may collect information about how you access and use the website, including your IP address, browser type, pages visited, and time spent on the site.</li>\r\n                        <li><strong>Cookies:</strong> This website may use cookies to enhance user experience and analyze website traffic.</li>\r\n                    </ul>\r\n                </div>\r\n            </section>\r\n\r\n            <section class=\"privacy-section\">\r\n                <h2 class=\"section-title\">\r\n                    <i class=\"fas fa-cogs\"></i>\r\n                    How I Use Information\r\n                </h2>\r\n                <div class=\"section-content\">\r\n                    <p>The information I collect is used for the following purposes:</p>\r\n                    <ul class=\"privacy-list\">\r\n                        <li>To respond to your inquiries and provide customer support</li>\r\n                        <li>To improve website functionality and user experience</li>\r\n                        <li>To analyze website traffic and usage patterns</li>\r\n                        <li>To comply with legal obligations</li>\r\n                    </ul>\r\n                </div>\r\n            </section>\r\n\r\n            <section class=\"privacy-section\">\r\n                <h2 class=\"section-title\">\r\n                    <i class=\"fas fa-share-alt\"></i>\r\n                    Information Sharing\r\n                </h2>\r\n                <div class=\"section-content\">\r\n                    <p>I do not sell, trade, or otherwise transfer your personal information to third parties, except in the following circumstances:</p>\r\n                    <ul class=\"privacy-list\">\r\n                        <li>With your explicit consent</li>\r\n                        <li>To comply with legal requirements or court orders</li>\r\n                        <li>To protect my rights, property, or safety, or that of others</li>\r\n                        <li>In connection with a business transfer or merger</li>\r\n                    </ul>\r\n                </div>\r\n            </section>\r\n\r\n            <section class=\"privacy-section\">\r\n                <h2 class=\"section-title\">\r\n                    <i class=\"fas fa-cookie-bite\"></i>\r\n                    Cookies and Tracking\r\n                </h2>\r\n                <div class=\"section-content\">\r\n                    <p>This website may use cookies and similar tracking technologies to:</p>\r\n                    <ul class=\"privacy-list\">\r\n                        <li>Remember your preferences and settings</li>\r\n                        <li>Analyze website traffic and user behavior</li>\r\n                        <li>Improve website performance and functionality</li>\r\n                    </ul>\r\n                    <p>You can control cookies through your browser settings. However, disabling cookies may affect website functionality.</p>\r\n                </div>\r\n            </section>\r\n\r\n            <section class=\"privacy-section\">\r\n                <h2 class=\"section-title\">\r\n                    <i class=\"fas fa-shield-alt\"></i>\r\n                    Data Security\r\n                </h2>\r\n                <div class=\"section-content\">\r\n                    <p>I implement appropriate security measures to protect your personal information against unauthorized access, alteration, disclosure, or destruction. However, no method of transmission over the internet is 100% secure.</p>\r\n                    <div class=\"security-measures\">\r\n                        <div class=\"security-item\">\r\n                            <i class=\"fas fa-lock\"></i>\r\n                            <span>SSL Encryption</span>\r\n                        </div>\r\n                        <div class=\"security-item\">\r\n                            <i class=\"fas fa-server\"></i>\r\n                            <span>Secure Hosting</span>\r\n                        </div>\r\n                        <div class=\"security-item\">\r\n                            <i class=\"fas fa-user-shield\"></i>\r\n                            <span>Access Controls</span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </section>\r\n\r\n            <section class=\"privacy-section\">\r\n                <h2 class=\"section-title\">\r\n                    <i class=\"fas fa-user-cog\"></i>\r\n                    Your Rights\r\n                </h2>\r\n                <div class=\"section-content\">\r\n                    <p>You have the following rights regarding your personal information:</p>\r\n                    <ul class=\"privacy-list\">\r\n                        <li><strong>Access:</strong> Request access to your personal information</li>\r\n                        <li><strong>Correction:</strong> Request correction of inaccurate information</li>\r\n                        <li><strong>Deletion:</strong> Request deletion of your personal information</li>\r\n                        <li><strong>Portability:</strong> Request transfer of your data to another service</li>\r\n                        <li><strong>Objection:</strong> Object to processing of your personal information</li>\r\n                    </ul>\r\n                </div>\r\n            </section>\r\n\r\n            <section class=\"privacy-section\">\r\n                <h2 class=\"section-title\">\r\n                    <i class=\"fas fa-external-link-alt\"></i>\r\n                    Third-Party Services\r\n                </h2>\r\n                <div class=\"section-content\">\r\n                    <p>This website may contain links to third-party websites or services. I am not responsible for the privacy practices of these external sites. I encourage you to review the privacy policies of any third-party sites you visit.</p>\r\n                    <div class=\"third-party-services\">\r\n                        <div class=\"service-item\">\r\n                            <i class=\"fab fa-google\"></i>\r\n                            <span>Google Analytics (if used)</span>\r\n                        </div>\r\n                        <div class=\"service-item\">\r\n                            <i clas